script.display_value:
(function executeRule(current, previous /*null when async*/ ) {

    var tID = current.sys_id.toString(),
        logDeTodo = false,
        msgHistorico,
        mtrID,
        mtrName,
        mtrTipoCambio,
        horaInicio = new GlideDateTime(),
        rID,
        rNumber = current.request_item.getDisplayValue().toString(),
        rNoEjecucion;

    var msgLog = 'JJ_MDM_Cambio_MKT_' + rNumber;

    if (logDeTodo)
        gs.log('000 Entro ', msgLog);

    var gr01 = new GlideRecord('sc_req_item');
    gr01.addEncodedQuery('sys_id=' + current.request_item);
    gr01.query();
    gr01.next();
    rID = gr01.sys_id;
    rNoEjecucion = gr01.u_mdm_ejecuciones_no.toString();
    mtrTipoCambio = gr01.variables.tipo_de_solicitud.toString();

    if (rNoEjecucion == '1') {

        msgHistorico = 'Cambio MKT ' + gr01.number + ' ' + new jj_Fecha_Mx().fechaHoyMx_MDM_hoy_hora();

        var gr02 = new GlideRecord('x_nsadc_tables_mdm_material_cambio_mkt');
        gr02.addEncodedQuery('u_mkt_ritm=' + rID);
        gr02.query();
        gr02.u_mkt_task = tID;
        gr02.updateMultiple();
        if (logDeTodo)
            gs.log('001 ' + current.number + ' Update ', msgLog);

        // Tiempo de espera
        gs.sleep(5000);

        var iConta = 0;
        var gr13 = new GlideRecord('x_nsadc_tables_mdm_material_cambio_mkt');
        gr13.addEncodedQuery('u_mkt_ritm=' + rID);
        gr13.query();
        while (gr13.next()) {

            if (logDeTodo)
                gs.log('002 MDM_Reg.  ', msgLog);


            mtrID = gr13.u_mkt_material_original;
            mtrName = gr13.u_mkt_descripcion_larga_de_producto.toString();

            var gr12 = new GlideRecord('u_mdm_registros');
            gr12.addEncodedQuery('sys_id=' + mtrID);
            gr12.query();
            if (gr12.next()) {

                gr12.setWorkflow(false);

                gr12.u_mt_historico = msgHistorico;
                gr12.u_mt_nombre = mtrName;
                gr12.u_mt_ecommerce = gr13.u_mkt_keyword;

                // Actualizar campos 
                var respuestaTask00 = new jj_MDM_Utils_Client().mdm_ActualizarName(mtrID, mtrName);
                gs.sleep(500); // Pausa de 0.5 segundo
                var strArray = respuestaTask00.toString().split('zzRespUestazz');

                gr12.u_mt_keywords_complementario = strArray[0];
                gr12.u_mt_metadescripcion = strArray[1];
                gr12.u_mt_caption_link = strArray[2];

                gr12.update();

            }
            if (logDeTodo)
                gs.log('Update EAN: ' + iConta + ' - ' + gr13.u_mkt_ean_pieza, msgLog);


            gr13.setWorkflow(false);
            if (mtrTipoCambio == '6451a9b32bb436d0677df2f9ed91bff9') {
                // "Uno a uno"	
            } else {
                // "Masivo"		
                gr13.u_mkt_keyword_comple = strArray[0];
                gr13.u_mtr_metadescripcion = strArray[1];
                gr13.u_mtr_caption_link = strArray[2];
            }
            gr13.u_mkt_estatus = 'Aprobado';
            gr13.u_mkt_random = '';
            gr13.update();


            iConta++;
            if ((iConta % 100) == 0)
                gs.log('UpDate Reg: ' + iConta, msgLog);
        }
        // Ultimo
        gs.log('UpDate Reg: ' + iConta + ' --- FIN', msgLog);




        var gr03 = new GlideRecord('sc_task');
        gr03.addEncodedQuery('sys_id=' + tID);
        gr03.query();
        gr03.next();
        gr03.state = 3;
        gr03.update();
        if (logDeTodo)
            gs.log('002 Closed ', msgLog);




    }
    if (logDeTodo)
        gs.log('zZz FIN zZz', msgLog);


    var msgFinalReturn = jjTiempoTotal(horaInicio, 'Listo');
    gs.log('99999\n\nMDM Materiales Cambio MKT "Modificado"' + msgFinalReturn, msgLog);

})(current, previous);







