script.display_value:
var msgLogEmail = '_MDM_BR_Task_Hijo_C',
	tempMsg= '\n\n';

(function executeRule(current, previous /*null when async*/ ) {

    msgLogEmail = current.request_item.getDisplayValue() +'_0'+current.u_mdm_etapa+'_'+ msgLogEmail;

	// gs.log('Entro', msgLogEmail);

    var gr00 = new GlideRecord('u_mdm_registros');
    gr00.addEncodedQuery('u_ritm=' + current.request_item);
    gr00.query();
    if (gr00.next()) {

        // Asignar Material a "Task"
        // La asignacion de materiales se realiza mientras espera "Flujo de cambio" en el Workflow

		// Los cambios solo se pueden crear desde widget
		// - Cambio normal
		// - Cambio cambrica
		// - Cambio masivo


        // [0] - PROVEEDOR (Etapa0) 
        // [1] - COMPRADOR
        // [2] - ASUNTOS REGULATORIOS
        // [3] - MKT
        // [4] - MM

		// 441ae9871bfd9610a9f8766dcc4bcbc3 - Modificacion sin flujo MM





        var varEmail = 'jj@gmail.com',
            varEtapa = gr00.u_mt_etapa_actual;


		// Material es el registro del cambio solicitado
		current.u_mdm_material_actual = gr00.u_mtr_cambio_material_origen;
		current.u_mdm_material_cambio = gr00.sys_id;
		// Asignacion
		if (varEtapa == 1) 
			current.assigned_to = gr00.u_mt_comprador;
		current.update();

		tempMsg += 'MTR_Actual: '+current.u_mdm_material_actual+' / '+ current.u_mdm_material_actual.getDisplayValue()+'\n';
		tempMsg += 'MTR_Cambio: '+current.u_mdm_material_cambio+' / '+ current.u_mdm_material_cambio.getDisplayValue()+'\n';
		tempMsg+= '\n';	
		tempMsg += 'Asignado: '+current.assignment_group.getDisplayValue()+' / '+ current.assigned_to.getDisplayValue()+'\n';
		tempMsg+= '\n';	


        if (varEtapa == 1) {
            // [1] - COMPRADOR
            varEmail = gr00.u_mt_comprador.email.toString();
            gs.eventQueue('mdm.mt.task.nueva', current, varEmail, '');
        } else if (varEtapa == 2) {
            // [2] - ASUNTOS REGULATORIOS
            varEmail = getEmailGrupal('73975fb797468e90cc1ebbdfe153af82'); // MDM_02_Asuntos_Regulatorios
            gs.eventQueue('mdm.mt.task.nueva', current, varEmail, '');
        } else if (varEtapa == 3) {
            // [3] - MKT
            varEmail = getEmailGrupal('6cd75fbb97468e90cc1ebbdfe153afbd'); // MDM_03_Mercadotecnia
            gs.eventQueue('mdm.mt.task.nueva', current, varEmail, '');
        } else if (varEtapa == 4) {
            // [4] - OPERACIONES
            varEmail = getEmailGrupal('1666508d1bc11a10a9f8766dcc4bcb51'); // MDM_04_Operaciones
            gs.eventQueue('mdm.mt.task.nueva', current, varEmail, '');
        } else if (varEtapa == 5) {
            // [5] - Maestro de articulos
            varEmail = getEmailGrupal('9b08ff94971b4650cc1ebbdfe153afbc'); // MDM_07_Analista Sr
            gs.eventQueue('mdm.mt.task.nueva', current, varEmail, '');
        } else if (varEtapa == 6) {
            // [6] - Maestro de articulos
            varEmail = getEmailGrupal('9b08ff94971b4650cc1ebbdfe153afbc'); // MDM_07_Analista Sr
            gs.eventQueue('mdm.mt.task.nueva', current, varEmail, '');
        }


        // gs.eventQueue("<event_name>", object, parm1, parm2);
        gs.log('RITM: ' + gr00.u_ritm.getDisplayValue() + '\nTask: ' + current.number + '\nEtapa: ' + varEtapa + '\nEmail(s): ' + varEmail+ tempMsg, msgLogEmail);
        // gs.log(current, msgLogEmail); // Task
    }
})(current, previous);





// -------------------------------- Regresa email del grupo consultado --------------------------------
function getEmailGrupal(varGrupoID) {
    var respUsers = '',
        iCont = 1;
    var gr02 = new GlideRecord('sys_user_grmember');
    gr02.addEncodedQuery('group=' + varGrupoID);
    gr02.query();
    while (gr02.next()) {
        respUsers += (iCont == 1) ? '' : ',';
        respUsers += gr02.user.email.toString();
        iCont++;
    }
    // gs.log(respUsers, msgLogEmail);
    return respUsers;
}

