function diferenciaEnDias(valor01, valor02) {

    var whatTime01 = new GlideDateTime(valor01); 
    var whatTime02 = new GlideDateTime(valor02); 

    var whatTime = GlideDateTime.subtract(whatTime01, whatTime02);
    var whatTime_Time = whatTime.getDisplayValue();
    var whatTime_Dia = whatTime.getDate(); // Dia 0 = '1970-01-01'
	return whatTime_Time;

}

