(function executeRule(current, previous /*null when async*/ ) {

    // var vaRitmID = '68dd7a851bf10e10a9f8766dcc4bcb32';
    var vaRitmID = current.sys_id.toString();


    // Material "0000" - 441ae9871bfd9610a9f8766dcc4bcbc3	

    var mdmID,
        mtrNum,
        mtrNumTask,
        mtrOriginal000 = '441ae9871bfd9610a9f8766dcc4bcbc3', // El mismo para las 3 instancias [DEV-TES-PROD]
        mtrTipoCambio,
        mtrNameL,
        mtrKeywordecomm,
        mtrKeywordcomple,
        mtrMetadescript,
        mtrCaptionlink,
        rPadreID,
        rPadreReq,
        rPadreOpen,
        rPadreRandom,
        vLogALL = false;

    if (vLogALL) {
        gs.log('00 Entro', msgLog);
        gs.log('01 RITM: ' + vaRitmID, msgLog);
    }

    var gr01 = new GlideRecord('sc_req_item');
    gr01.addEncodedQuery('sys_id=' + vaRitmID);
    gr01.query();
    if (gr01.next()) {
        gr01.quantity = 1;
        gr01.u_mdm_etapa = '8';
        gr01.u_mdm_enviado_sap_no = 0;
        gr01.u_mdm_ejecuciones_no = 1;
        gr01.u_mdm_material = mtrOriginal000;
        gr01.u_mdm_flujo = '1';
        mtrTipoCambio = gr01.variables.tipo_de_solicitud.toString();

        if (mtrTipoCambio == '6451a9b32bb436d0677df2f9ed91bff9') {
            // "Uno a uno"		
            gr01.short_description = 'MDM Material Cambio MKT [Uno a uno]';
        } else {
            // "Masivo"		
            gr01.short_description = 'MDM Material Cambio MKT [Masivo]';
        }

