        mtrKeywordcomple = gr01.variables.mtr_keyword_comple.toString();
        mtrMetadescript = gr01.variables.mtr_metadescripcion.toString();
        mtrCaptionlink = gr01.variables.mtr_caption_link.toString();

        gr01.update();
        if (vLogALL)
            gs.log('03 RITM "SI" localizado', msgLog);
    } else {
        if (vLogALL)
            gs.log('03 RITM "NO" encontrado', msgLog);
    }

    if (vLogALL)
        gs.log('04 Random: ' + rPadreRandom, msgLog);


    // Actuializar tabla "MDM Material Cambio MKTs"
    var gr13 = new GlideRecord('x_nsadc_tables_mdm_material_cambio_mkt');
    gr13.addEncodedQuery('u_mkt_random=' + rPadreRandom);
    gr13.query();
    gr13.u_mkt_ritm = vaRitmID;
    gr13.u_mkt_estatus = 'En Proceso';
